var getIndex = function(reader) {
    let l = 0, r = reader.length() - 1;
    while (l < r) {
        const len = r - l + 1;
        const half = Math.floor(len / 2);
        if (len % 2 === 0) {
            const cmp = reader.compareSub(l, l + half - 1, l + half, r);
            if (cmp >= 0) r = l + half - 1;
            else l = l + half;
        } else {
            const cmp = reader.compareSub(l, l + half - 1, l + half + 1, r);
            if (cmp === 0) return l + half;
            if (cmp === 1) r = l + half - 1;
            else l = l + half + 1;
        }
    }
    return l;
};
